sys_variable_value.value:
(function execute(inputs, outputs) {

    var base64Str = gs.base64Encode(inputs.raw_url);

    var base64url = base64Str.replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
    
    outputs.encoded_url = base64url;
})(inputs, outputs);

