sys_variable_value.value:
(function execute(inputs, outputs) {
    try {
        var response = JSON.parse(inputs.response_body);
        var maliciousFlags = response.data.attributes.last_analysis_stats.malicious;
        
        outputs.malicious_count = maliciousFlags.toString();
        
        if (maliciousFlags > 0) {
            outputs.threat_status = "Malicious URL Detected (" + maliciousFlags + " engines flagged)";
        } else {
            outputs.threat_status = "URL Clean";
        }
    } catch (e) {
        outputs.threat_status = "Error parsing URL data: " + e.message;
        outputs.malicious_count = "0";
    }
})(inputs, outputs);

